import Component from 'flarum/common/Component';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import PredictionCard from './PredictionCard';
import { lookup } from '../data';
/**
 * Cards inside a post or under a discussion's first post are their own
 * Mithril roots (m.mount), not children of the post: the post's subtree
 * retainer skips redraws until the POST changes, so a child card would never
 * show its data or a new pick. A root is redrawn by every m.redraw(), and
 * unmounts itself once the post has replaced the element it lives in.
 */
class Cards extends Component {
  found = null;
  oninit(vnode) {
    super.oninit(vnode);
    Promise.all(this.attrs.ids.map(lookup)).then(all => {
      this.found = all.filter(p => !!p);
      m.redraw();
    });
  }
  view() {
    if (!this.attrs.host.isConnected) {
      window.setTimeout(() => m.mount(this.attrs.host, null), 0);
      return null;
    }
    if (!this.found) return this.attrs.context === 'discussion' ? m(LoadingIndicator, {
      display: "block",
      size: "small"
    }) : null;
    return this.found.map(p => m(PredictionCard, {
      key: p.id,
      prediction: p,
      context: this.attrs.context,
      ondelete: () => this.found = this.found.filter(f => f !== p)
    }));
  }
}
export function mountCards(host, ids, context) {
  m.mount(host, {
    view: () => m(Cards, {
      ids: ids,
      context: context,
      host: host
    })
  });
}
flarum.reg.add('ernestdefoe-predictions', 'forum/components/mount', { mountCards: mountCards, });